157384fa976b73d983ddc2be26d19e7e17b17"],"questions":[{"sourceKey":"source:kwangwoon-2026-mock-natural-single:q1","id":"c571234a-dd0c-5617-8142-6c84b2e46c21","label":"문제 1","order":0},{"sourceKey":"source:kwangwoon-2026-mock-natural-single:q2","id":"e72b96c2-1286-5fb9-a02c-431cbccd8daa","label":"문제 2","order":1}]},{"sourceKey":"source:kwangwoon-2027-mock-natural-single","examId":"6f01f238-622d-5a85-9a04-8bb5a7b9759d","existingExam":false,"universityId":"3d35489f-2e90-47b8-af1b-48928ee2269a","year":2027,"kind":"mock","track":"자연계열","session":null,"campus":null,"examKey":"source-kwangwoon-2027-mock-natural-single","name":"광운대학교 2027학년도 모의논술 자연계열","sourceHashes":["bb491add0733d8b1b79483a664f9eda7b32a833614d3d62e04398ee734db4bd5"],"questions":[{"sourceKey":"source:kwangwoon-2027-mock-natural-single:q1","id":"cc580066-bed4-5fda-8eb6-cab0d26500b7","label":"문제 1","order":0},{"sourceKey":"source:kwangwoon-2027-mock-natural-single:q2","id":"b23b4bae-a23e-5e1a-b0d0-b0e04a163c3e","label":"문제 2","order":1}]}]$registration$::jsonb) loop
  if exists(select 1 from public.essay_questions where essay_exam_id=(e->>'examId')::uuid and id not in (select (value->>'id')::uuid from jsonb_array_elements(e->'questions'))) then raise exception 'UNPLANNED_QUESTIONS_EXIST';end if;
  for fk in select c.conrelid,c.confrelid,c.conkey,c.confkey,a.attname from pg_constraint c cross join lateral generate_subscripts(c.confkey,1) pos(n) join pg_attribute target on target.attrelid=c.confrelid and target.attnum=c.confkey[pos.n] and target.attname='id' join pg_attribute a on a.attrelid=c.conrelid and a.attnum=c.conkey[pos.n] where c.contype='f' and c.confrelid in ('public.essay_exams'::regclass,'public.essay_questions'::regclass) and c.conrelid<>'public.essay_questions'::regclass loop
   if fk.confrelid='public.essay_exams'::regclass then ids=array[(e->>'examId')::uuid];else select array_agg((value->>'id')::uuid) into ids from jsonb_array_elements(e->'questions');end if;
   execute format('select exists(select 1 from %s where %I=any($1))',fk.conrelid::regclass,fk.attname) into hit using ids;
   if hit then raise exception 'DEPENDENT_RECORDS_EXIST';end if;
  end loop;
  for q in select value from jsonb_array_elements(e->'questions') loop
   expected=jsonb_build_object('id',q->>'id','essay_exam_id',e->>'examId','question_key',q->>'sourceKey','label',q->>'label','display_order',(q->>'order')::int,'metadata_version','source-registration-v1','is_published',false);
   select jsonb_strip_nulls(to_jsonb(x)-'created_at') into actual from public.essay_questions x where id=(q->>'id')::uuid;
   if found and actual is distinct from expected then raise exception 'QUESTION_STATE_CHANGED';end if;
   if exists(select 1 from public.essay_practice_sessions where question_id=(q->>'id')::uuid) then raise exception 'LEARNING_RECORDS_EXIST';end if;
   delete from public.essay_questions where id=(q->>'id')::uuid;
  end loop;
  if not (e->>'existingExam')::boolean then
   expected=jsonb_strip_nulls(jsonb_build_object('id',e->>'examId','university_id',e->>'universityId','admission_year',(e->>'year')::int,'exam_key',e->>'examKey','exam_name',e->>'name','exam_kind',e->>'kind','campus',e->>'campus','field_or_division',e->>'track','session_label',e->>'session','verification_status','review','is_active',false));
   select jsonb_strip_nulls(to_jsonb(x)-array['created_at','updated_at']) into actual from public.essay_exams x where id=(e->>'examId')::uuid;
   if found and actual is distinct from expected then raise exception 'EXAM_STATE_CHANGED';end if;
   delete from public.essay_exams where id=(e->>'examId')::uuid;
  end if;
 end loop;
end $body$;
commit;
